import { defineConfig } from "vite-plus";
import type { OxlintOverride } from "vite-plus/lint";

const ignorePatterns = [
  // Generated by @tanstack/router-plugin. Committed so type checks work before a build.
  "**/routeTree.gen.ts",
  // Generated by kysely-codegen from the migrations (pnpm exec nx db-types db, docs/adr/0025). Committed; CI checks
  // that they match the migrations. Still type-checked through the files that import them.
  "packages/*/src/infrastructure/db.gen.ts",
  // Agent skills installed from upstream (tracked by skills-lock.json). Must stay byte-identical.
  ".agents/**",
  // Symlinks to .agents/skills. The rest of .kiro/ (hooks, settings, steering) is checked like any other file.
  ".kiro/skills/**",
];

// Fixtures whose disable comments name rules of the effecttsgo plugin. Only `effect-tsgo oxlint` loads the plugin
// (oxlint.effect.json), so for `vp lint` the comments would be unused (docs/tooling/effect-lint.md).
const effectOnlyFixtures = ["packages/*/src/*/__fixtures__/effect-tsgo.ts"];

const runtimeImportMessage =
  "Runtime-specific code belongs in an entry file such as apps/api/src/server.ts (docs/adr/0007).";

const runtimeImports = {
  paths: [
    { name: "bun", message: runtimeImportMessage },
    { name: "@hono/node-server", message: runtimeImportMessage },
    { name: "@hono/aws-lambda", message: runtimeImportMessage },
    { name: "@hono/node-ws", message: runtimeImportMessage },
  ],
  patterns: [{ group: ["bun:*"], message: runtimeImportMessage }],
};

// Imports that bypass the Outbox and the transaction (docs/adr/0029). A request or a module that calls SQS, SES and the
// like directly sends before the transaction commits, or twice on a retry; a module that opens a connection of its own
// skips the tenant setting and the module role of inTenantTransaction. The names are in two arrays, and repo-policy
// checks that every override that stops them has a fixture for each name (#43). Oxlint keeps only the last override
// that sets a rule for a file, so each override below carries its own copy of the `paths`:
//   - packages/*/src, each of its layers, and apps/api/src stop both lists;
//   - the entry files and the tests of apps/api/src, and packages/db/src, may open a connection (they make the pool,
//     docs/adr/0038) but not send, so they stop the SDK clients only. Add the entry file of the relay and of the
//     consumers to the override of the entry files when they exist, and remove the SDK clients from it there.
// A file that has to open a connection, such as a databases.ts that makes the pool (today it only imports the type
// of Pool), is an entry file: add it to the override of the entry files below. This is a guardrail: a `fetch` to an AWS
// endpoint and a dynamic import are not stopped.
const outboxPackages = [
  "@aws-sdk/client-sqs",
  "@aws-sdk/client-ses",
  "@aws-sdk/client-sesv2",
  "@aws-sdk/client-sns",
  "@aws-sdk/client-eventbridge",
  "@aws-sdk/client-lambda",
  "@aws-sdk/client-sfn",
];
const connectionPackages = ["pg"];
const outboxBypassMessage =
  "Do not send to SQS, SES, SNS, EventBridge, Lambda or Step Functions from a module or a request: put the event in " +
  "the Outbox with enqueueOutbox, in the same transaction as the update, and let the relay or a consumer send it " +
  "(docs/adr/0029). A place that may send is an entry file, added to the override of the entry files.";
const connectionMessage =
  "Do not open a connection of your own: it skips the tenant setting and the module role. Open a transaction with " +
  "inTenantTransaction (docs/adr/0011, docs/adr/0029 rule 2). A type import is fine; the pool is made in the entry file.";
const outboxPaths: RestrictedPath[] = outboxPackages.map((name) => ({
  name,
  message: outboxBypassMessage,
}));
const connectionPaths: RestrictedPath[] = connectionPackages.map((name) => ({
  name,
  allowTypeImports: true,
  message: connectionMessage,
}));
const bypassPaths = [...outboxPaths, ...connectionPaths];

// Raw SQL and the way around the module's types (docs/adr/0029). A module reads and writes its own tables through the
// typed Kysely builder. The `sql` tag and `CompiledQuery` take any text, so they could reach the table of another
// module with a type that nobody checks; the module role of the database stops that at runtime (docs/adr/0029), and
// this stops it before. shared (the helper of the transaction) and apps/api are outside this list: shared owns the SQL that sets the
// role and the tenant, and the rule of tools/lint-plugins/src/tenant-sql-plugin.ts reads what they write.
const sqlImportNames = ["sql", "CompiledQuery"];
const sqlMessage =
  "Do not write raw SQL in a module: `sql` and `CompiledQuery` skip the types of the Kysely builder, so a query can " +
  "reach a table of another module. Use the builder on your own tables, and read another module's data through its " +
  "public API function (docs/adr/0029). If a query truly needs raw SQL, put the reason on the disable comment.";
const sqlPaths: RestrictedPath[] = [
  { name: "kysely", importNames: sqlImportNames, message: sqlMessage },
];

// `withTables` gives a transaction the types of another database. It is called in infrastructure/ only, inside a public
// API function that takes the caller's transaction to read its own tables (docs/adr/0029).
const withTablesMessage =
  "Call withTables only in infrastructure/, in the public API function that reads your own tables with the " +
  "transaction of the caller. Elsewhere, read another module's data through its public API function (docs/adr/0029).";
const withTablesEntry = { property: "withTables", message: withTablesMessage };

// Runtime-specific globals (docs/adr/0007), with the fix to name in the message. runtimeGlobalLintRules turns them
// into rules: no-restricted-globals stops the bare name, and no-restricted-properties stops the same name read
// from globalThis.
const runtimeGlobals = [
  {
    name: "process",
    message:
      "Read environment variables only in the entry file and pass them to the app as arguments (docs/adr/0032).",
  },
  { name: "Bun", message: runtimeImportMessage },
  { name: "Buffer", message: "Use Uint8Array, TextEncoder or TextDecoder." },
];
const runtimeGlobalEntries = [
  ...runtimeGlobals,
  // global.process is the Node.js alias of globalThis.process, and no-restricted-properties cannot name it.
  {
    name: "global",
    message:
      "Do not use `global`: it is the Node.js alias of `globalThis`, and it hides `process` and the other runtime globals. Use only the Web standard globals.",
  },
  { name: "__dirname", message: "Use `import.meta.url`." },
  { name: "__filename", message: "Use `import.meta.url`." },
  { name: "require", message: "Use `import`." },
];
const runtimePropertyEntries = runtimeGlobals.map(({ name, message }) => ({
  object: "globalThis",
  property: name,
  message: `${message} (\`globalThis.${name}\` is the same global.)`,
}));
// Reading the clock (docs/adr/0043). Only an entry point reads the current time, once, from the Effect `Clock` (currentInstant
// of packages/shared), and passes it down as `now`. So `Date` as a value (`new Date()`, `Date.now()`) and
// `Temporal.Now` are stopped, also from globalThis (a `Date` in a type annotation is not reported). A library that
// needs a `Date` takes a disable comment with the reason.
const clockMessage = (instead: string) =>
  `Do not read the clock here: ${instead}, so that a test fixes the time and one request has one time ` +
  "(docs/adr/0043, docs/domain-model/application-effect.md).";
const entryClockMessage = clockMessage(
  "an entry point reads it once with currentInstant of @agent-software-factory/shared and passes it down as `now`",
);
function clockEntries(message: string) {
  return {
    globals: [{ name: "Date", message }],
    properties: [
      { object: "Temporal", property: "Now", message },
      { object: "globalThis", property: "Temporal", message },
      { object: "globalThis", property: "Date", message },
    ],
  };
}
const entryClockLint = clockEntries(entryClockMessage);
// The domain override sets the same two rules for its own purposes (domainPurityRules), and Oxlint keeps only
// the last override that sets a rule, so it spreads the entries above into its lists.
const runtimeGlobalLintRules = {
  "no-restricted-globals": ["error", ...runtimeGlobalEntries, ...entryClockLint.globals],
  "no-restricted-properties": [
    "error",
    ...runtimePropertyEntries,
    ...entryClockLint.properties,
    withTablesEntry,
  ],
} satisfies Record<string, ["error", ...Record<string, string>[]]>;

// Module boundaries (docs/adr/0026). The sample feature is a modular monolith: each module is a package under
// packages/, and apps/api only assembles them. Which module may import which (closing (締め) → approval (承認)
// → claim (申請), shared imports none) is not a lint rule: a module can resolve only the packages its
// package.json declares (pnpm, TypeScript), and repo-policy checks the declarations. The rules here are the same
// for every module, so one override per layer reaches them all, and packages/module-fixtures holds the fixtures.
const scope = "@agent-software-factory";
// The React code: the app, and the parts it shares (packages/ui, docs/adr/0034). Their React, console and XSS rules
// are the same.
const webFiles = ["apps/web/src/**", "packages/ui/src/**"];
// The layers of a module (src/<layer>/), with the layers each may import. domain imports nothing but the types of
// shared (below).
const layers: Record<string, readonly string[]> = {
  domain: [],
  application: ["domain"],
  infrastructure: ["application", "domain"],
  http: ["application", "domain"],
};

const deepMessage =
  `Import another package by its name only (${scope}/<name>). Its package.json exports its src/index.ts and ` +
  "nothing else; export what you need from there (docs/adr/0026).";
const dbMessage =
  "db imports the packages of the workspace by `import type` only: it knows the database types of the modules, not " +
  "their code. Use `import type`, or move the code to apps/api (docs/adr/0038).";
const layerMessage =
  "Layers point inward: domain imports nothing, application imports domain, and infrastructure and http import " +
  "application and domain but not each other (docs/adr/0026).";
const domainMessage =
  `domain imports nothing but types of ${scope}/shared (\`import type\`). Put the code that needs a library or ` +
  "another module in application or infrastructure (docs/adr/0026).";

// Effect (docs/adr/0028). The features that the ADR does not use are each done by another tool already: validation
// by zod, logs by stdout, retries by ky and the SDKs. The `unstable` and `experimental` APIs are stopped by
// effect-tsgo (oxlint.effect.json, docs/tooling/effect-lint.md), which can read the @stability tag.
const unusedEffectModules = [
  "Schema",
  "Logger",
  "Config",
  "ConfigProvider",
  "Schedule",
  "Stream",
  "Queue",
  "Fiber",
  "FiberHandle",
  "FiberMap",
  "FiberSet",
];
// Subpaths of effect that are whole unstable modules (HTTP, HTTP API, SQL).
const unusedEffectSubpaths = ["http", "http-api", "sql"];
const unusedEffectMessage =
  "This Effect feature is not used: validation is zod, logs are stdout, retries are ky and the SDKs. Use only " +
  "the features listed in docs/domain-model/application-effect.md (docs/adr/0028).";
const unusedSqlMessage =
  "@effect/sql* is not used: the database is Kysely, wrapped by Effect.tryPromise in infrastructure " +
  "(docs/adr/0025, docs/adr/0028).";
interface RestrictedPath {
  name: string;
  message: string;
  importNames?: string[];
  allowTypeImports?: boolean;
}
// Added to every layer but domain, which may import no library at all (domainMessage above).
const effectPaths: RestrictedPath[] = [
  { name: "effect", importNames: unusedEffectModules, message: unusedEffectMessage },
];
const effectPatterns = [
  {
    regex: `^effect/(?:${[...unusedEffectModules, ...unusedEffectSubpaths].join("|")})(?:/|$)`,
    message: unusedEffectMessage,
  },
  { regex: "^@effect/sql(?:$|-|/)", message: unusedSqlMessage },
];

// Every function that runs an Effect: Effect.run*, and the same names on a ManagedRuntime. Matched by the name
// of the property, so an alias of Effect or a runtime held in a variable is stopped too.
const effectRunFunctions = [
  "runCallback",
  "runCallbackWith",
  "runFork",
  "runForkWith",
  "runPromise",
  "runPromiseExit",
  "runPromiseExitWith",
  "runPromiseWith",
  "runSync",
  "runSyncExit",
  "runSyncExitWith",
  "runSyncWith",
];
const effectRunMessage =
  "application and infrastructure return an Effect and never run it: running it there drops the failure and " +
  "dependency types. Run it in http, an entry point or a test (docs/adr/0028).";

// Imports that reach past the index.ts of another package: a subpath of the package name, or a relative path
// into the src/ of a package or an app. The package.json exports stop the first from resolving, and this rule
// names both.
const subpathImport = { regex: `^${scope}/[^/]+/`, message: deepMessage };
const relativeDeepImport = { regex: "^\\.{1,2}/(?:.*/)?[^/]+/src(?:/|$)", message: deepMessage };
const deepImports = [subpathImport, relativeDeepImport];

// What the tests of apps/api may import past the index.ts of a package: the tools of the tests and the seed of
// packages/db (docs/adr/0038). Production code in apps/api/src does not, so it stays under deepImports.
const dbSubpaths = ["testing", "seed"];
const testDeepImports = [
  {
    group: [`${scope}/*/**`, ...dbSubpaths.map((path) => `!${scope}/db/${path}`)],
    message: deepMessage,
  },
  relativeDeepImport,
];

// The options of no-restricted-imports for a file of a package in `layer` (undefined: src/index.ts and other
// files outside the layers, and shared). Oxlint keeps only the last override that sets a rule for a file, so each
// override carries all the restrictions of its files.
// `shared` is not a module: it owns the SQL of the transaction helper, so it may import `sql` (sqlPaths).
function moduleImports(layer?: string, allowSql = false) {
  const patterns: Record<string, unknown>[] = [...runtimeImports.patterns, ...deepImports];
  if (layer !== undefined) {
    const other = Object.keys(layers).filter((l) => l !== layer && !layers[layer]?.includes(l));
    if (other.length > 0)
      patterns.push({
        regex: `^(?:\\./)?(?:\\.\\./)+(?:${other.join("|")})(?:/|$)`,
        message: layerMessage,
      });
  }
  if (layer === "domain")
    // Oxlint 1.89 checks the patterns in order, and a negated group that matches ends the check of that import.
    // So the value imports of shared are stopped first, then every package but shared.
    patterns.push(
      { regex: `^${scope}/shared$`, allowTypeImports: true, message: domainMessage },
      { regex: "^[^.@]", message: domainMessage },
      { group: ["@*/*", `!${scope}/shared`], message: domainMessage },
    );
  if (layer !== "domain") patterns.push(...effectPatterns);
  const paths: RestrictedPath[] = [...runtimeImports.paths, ...bypassPaths];
  if (!allowSql) paths.push(...sqlPaths);
  if (layer !== "domain") paths.push(...effectPaths);
  // application takes `now` as an argument; an entry point reads the Clock (docs/adr/0043).
  if (layer === "application")
    paths.push(
      { name: "effect", importNames: ["Clock"], message: entryClockMessage },
      { name: "effect/Clock", message: entryClockMessage },
    );
  if (layer === "application" || layer === "infrastructure")
    paths.push({
      name: "effect/Effect",
      importNames: effectRunFunctions,
      message: effectRunMessage,
    });
  return { paths, patterns };
}

// How domain is written (docs/adr/0027): pure functions that return a Result. domain takes the time and the
// randomness as arguments, and returns a failure instead of throwing it. The clock restrictions of clockEntries
// apply (`Date` as a value, `Temporal.Now`); the type `Date` in an annotation is not reported (checked with
// Oxlint 1.89.0, see the 出典 of docs/adr/0027).
// These rules join the no-restricted-imports of the domain override of each module, in the same object: Oxlint
// keeps only the last override that sets a rule for a file, so a second override for domain would drop one of
// the two (docs/adr/0026). Each rule has a fixture in packages/*/src/domain/__fixtures__/purity.ts (#43).
const domainPurityMessage = (what: string, instead: string) =>
  `${what} makes a domain function depend on something other than its arguments. ${instead}, ` +
  "and let application supply it (docs/adr/0027, docs/domain-model/types.md).";
const domainClockLint = clockEntries(
  domainPurityMessage("The current time", "Take the time as an argument, a `Temporal.Instant`"),
);
const domainPurityRules = {
  jsPlugins: [{ name: "domain", specifier: "./tools/lint-plugins/src/domain-plugin.ts" }],
  rules: {
    "domain/no-throw": "error",
    "no-restricted-globals": ["error", ...runtimeGlobalEntries, ...domainClockLint.globals],
    "no-restricted-properties": [
      "error",
      ...runtimePropertyEntries,
      ...domainClockLint.properties,
      withTablesEntry,
      {
        object: "Math",
        property: "random",
        message: domainPurityMessage(
          "`Math.random`",
          "Take the random value, or the id, as an argument",
        ),
      },
    ],
  },
} satisfies Pick<OxlintOverride, "jsPlugins" | "rules">;

const moduleOverrides: OxlintOverride[] = [
  {
    files: ["packages/*/src/**"],
    rules: { "no-restricted-imports": ["error", moduleImports()] },
  },
  ...Object.keys(layers).map((layer): OxlintOverride => {
    const files = [`packages/*/src/${layer}/**`];
    const imports: NonNullable<OxlintOverride["rules"]> = {
      "no-restricted-imports": ["error", moduleImports(layer)],
    };
    return layer === "domain"
      ? {
          files,
          jsPlugins: domainPurityRules.jsPlugins,
          rules: { ...imports, ...domainPurityRules.rules },
        }
      : { files, rules: imports };
  }),
];

// What the entry files and the tests of the runtime-specific rules turn off.
const runtimeRulesOff = {
  "import/no-nodejs-modules": "off",
  "no-restricted-globals": "off",
  "no-restricted-properties": "off",
} as const;

const childProcessMessage =
  "Start git and other processes through gitIn() or runIn() from tools/scripts/src/test/sandbox.ts, which refuse " +
  'to act outside the sandbox (docs/tooling/ci.md ("スクリプトのテスト")).';

// Rules of typescript-eslint's `recommended-type-checked` that Oxlint does not enable by default, plus three
// stricter ones (docs/adr/0020). They stop `any`, `!`, narrowing `as` and @ts-ignore, the ways to silence a
// type error. A description is required after @ts-expect-error.
const typedRules: Record<string, "error" | ["error", ...unknown[]]> = {
  "typescript/ban-ts-comment": ["error", { "ts-expect-error": "allow-with-description" }],
  "typescript/no-explicit-any": "error",
  "typescript/no-empty-object-type": "error",
  "typescript/no-namespace": "error",
  "typescript/no-require-imports": "error",
  "typescript/no-unnecessary-type-constraint": "error",
  "typescript/no-unsafe-function-type": "error",
  "typescript/no-misused-promises": "error",
  "typescript/no-unnecessary-type-assertion": "error",
  "typescript/no-unsafe-argument": "error",
  "typescript/no-unsafe-assignment": "error",
  "typescript/no-unsafe-call": "error",
  "typescript/no-unsafe-member-access": "error",
  "typescript/no-unsafe-return": "error",
  "typescript/no-unsafe-enum-comparison": "error",
  "typescript/only-throw-error": "error",
  "typescript/prefer-promise-reject-errors": "error",
  "typescript/require-await": "error",
  "typescript/restrict-plus-operands": "error",
  // Stricter than recommended-type-checked.
  "typescript/switch-exhaustiveness-check": "error",
  "typescript/no-non-null-assertion": "error",
  "typescript/no-unsafe-type-assertion": "error",
};

// Root config for `vp check` / `vp lint` / `vp fmt`.
// Task orchestration and caching are handled by Nx, not `vp run` (see docs/adr/0002).
export default defineConfig({
  fmt: {
    ignorePatterns,
  },
  lint: {
    ignorePatterns: [...ignorePatterns, ...effectOnlyFixtures],
    jsPlugins: [{ name: "vite-plus", specifier: "vite-plus/oxlint-plugin" }],
    // Oxlint 1.89.0 builds the module graph that import/no-cycle needs only when the root config lists the import
    // plugin; an override that lists it alone reports nothing (checked 2026-10-30). Listing plugins replaces
    // Oxlint's defaults, so they are named here too. The rules of the import plugin stay off but for the ones the
    // overrides turn on.
    plugins: ["import", "typescript", "unicorn", "oxc"],
    rules: {
      "vite-plus/prefer-vite-plus-imports": "error",
      ...typedRules,
    },
    options: {
      typeAware: true,
      typeCheck: true,
      // A warning fails `vp check` too. Without this a warning-level rule such as no-floating-promises
      // passes CI (docs/adr/0020).
      denyWarnings: true,
      reportUnusedDisableDirectives: "error",
    },
    overrides: [
      // Agent-written tests: block .only (runs a subset) and .skip (hides a failing test), and a test that
      // passes without checking anything: no expect, an expect that runs only on one branch, or an expect
      // that asserts nothing (#30). The last three are in Oxlint's correctness category, which listing the plugin
      // already turns on as warnings; they are named here so that they stay errors whatever the defaults.
      // tools/scripts/src/test/fixtures/expect.test.ts fails `vp check` if one is turned off.
      // See docs/code-review/agent-pull-requests.md.
      {
        files: ["**/*.test.ts", "**/*.test.tsx"],
        plugins: ["vitest"],
        rules: {
          "vitest/no-focused-tests": "error",
          "vitest/no-disabled-tests": "error",
          "vitest/expect-expect": "error",
          "vitest/no-conditional-expect": "error",
          "vitest/valid-expect": "error",
        },
      },
      // ADR 0007: apps/api/src uses Web standard APIs only, so the app runs on Node.js,
      // Lambda and Cloudflare Workers. Runtime-specific code lives in the entry files below.
      {
        files: ["apps/api/src/**", "packages/*/src/**"],
        plugins: ["import"],
        rules: {
          "import/no-nodejs-modules": "error",
          // apps/api imports the modules by their package names only (docs/adr/0026).
          "no-restricted-imports": [
            "error",
            {
              paths: [...runtimeImports.paths, ...bypassPaths],
              patterns: [...runtimeImports.patterns, ...deepImports],
            },
          ],
          ...runtimeGlobalLintRules,
        },
      },
      // A cycle between the files of a package or an app (docs/adr/0026). This override sets import/no-cycle and
      // nothing else, so it takes no rule from the overrides above and below: Oxlint keeps only the last override
      // that sets a given rule for a file, and none of the others sets this one. apps/web is reached too, which the
      // override for apps/api/src above is not. The fixture is packages/module-fixtures/src/__fixtures__/cycle-a.ts.
      {
        files: ["apps/*/src/**", "packages/*/src/**"],
        plugins: ["import"],
        rules: { "import/no-cycle": "error" },
      },
      // Runtime-specific entry files and tests. Add new entry files (Lambda, Workers, ...) here.
      // They still import the modules by their package names only (docs/adr/0026).
      {
        files: ["apps/api/src/server.ts", "apps/api/src/**/*.test.ts"],
        // A plugin rule can only be turned off in an override that also lists the plugin.
        plugins: ["import"],
        rules: {
          ...runtimeRulesOff,
          // They make the pool, so they may import pg; a send from here skips the Outbox as well, so the SDK clients
          // stay stopped (outboxPackages above).
          "no-restricted-imports": ["error", { paths: outboxPaths, patterns: testDeepImports }],
        },
      },
      // Tests of the packages. They leave the runtime restrictions of the override above, but not the import
      // restrictions of the modules, which are set in the overrides below (docs/adr/0026).
      {
        files: ["packages/*/src/**/*.test.ts"],
        plugins: ["import"],
        rules: runtimeRulesOff,
      },
      // Module boundaries (docs/adr/0026): imports by the package name only, and the direction between the layers
      // of a module. The direction between the modules is the dependencies of their package.json.
      ...moduleOverrides,
      // shared is not a module (docs/adr/0026): it holds the helper of the transaction, which writes SQL with `sql`.
      // It keeps every other restriction of the modules.
      {
        files: ["packages/shared/src/**"],
        rules: { "no-restricted-imports": ["error", moduleImports(undefined, true)] },
      },
      // packages/db is not a module (docs/adr/0038). It runs the migrations and starts containers, so it leaves the
      // runtime restrictions as an entry file does (docs/adr/0007), keeps the ban on deep imports, and imports the
      // packages of the workspace as types only. It has no layers, so the overrides above reach it only by
      // packages/*/src/**, which this override replaces.
      {
        files: ["packages/db/src/**"],
        plugins: ["import"],
        rules: {
          ...runtimeRulesOff,
          "no-restricted-imports": [
            "error",
            {
              // db opens the connections, so it may import pg, but it does not send.
              paths: outboxPaths,
              patterns: [
                ...deepImports,
                { regex: `^${scope}/[^/]+$`, allowTypeImports: true, message: dbMessage },
              ],
            },
          ],
        },
      },
      // application and infrastructure never run an Effect (docs/adr/0028); a test of them may. Each layer has a
      // fixture in <layer>/__fixtures__/effect.ts that this rule must report (repo-policy checks it).
      // This override replaces the no-restricted-properties of the override for all of packages/*/src, so it
      // carries that override's runtime globals and clock too. application also stops withTables, which only
      // infrastructure may call (withTablesEntry).
      {
        files: ["packages/*/src/application/**"],
        rules: {
          "no-restricted-properties": [
            "error",
            ...effectRunFunctions.map((property) => ({ property, message: effectRunMessage })),
            ...runtimePropertyEntries,
            ...entryClockLint.properties,
            withTablesEntry,
          ],
        },
      },
      {
        files: ["packages/*/src/infrastructure/**"],
        rules: {
          "no-restricted-properties": [
            "error",
            ...effectRunFunctions.map((property) => ({ property, message: effectRunMessage })),
            ...runtimePropertyEntries,
            ...entryClockLint.properties,
          ],
        },
      },
      {
        files: [
          "packages/*/src/application/**/*.test.ts",
          "packages/*/src/infrastructure/**/*.test.ts",
        ],
        rules: { "no-restricted-properties": "off" },
      },
      // Tests of tools/scripts run from Git hooks, where a git command can act on this repository instead of
      // the temporary one (docs/tooling/ci.md ("スクリプトのテスト")). They start processes only through the
      // helpers in tools/scripts/src/test/, which are not test files. Dynamic import() and createRequire are
      // outside this rule; tools/scripts/src/test/isolation.test.ts catches what they would do.
      {
        files: ["tools/scripts/src/**/*.test.ts"],
        rules: {
          "no-restricted-imports": [
            "error",
            {
              paths: [
                { name: "node:child_process", message: childProcessMessage },
                { name: "child_process", message: childProcessMessage },
              ],
            },
          ],
        },
      },
      // SQL that changes the role or the tenant of the connection is written in the helper of the transaction only
      // (docs/adr/0029). shared and apps/api are the places that may use `sql`; the modules may not (sqlPaths). The
      // rule is in tools/lint-plugins/src/tenant-sql-plugin.ts. The helper is the one file that sets them, and its
      // test sets and reads them to check the helper, so both are outside the rule; every other test is under it.
      // Fixtures that this rule must report: apps/api/src/__fixtures__/session-setting.ts and packages/shared/src/__fixtures__/session-setting.ts.
      {
        files: ["packages/shared/src/**", "apps/api/src/**"],
        jsPlugins: [
          { name: "tenant-sql", specifier: "./tools/lint-plugins/src/tenant-sql-plugin.ts" },
        ],
        rules: { "tenant-sql/no-session-setting": "error" },
      },
      {
        files: [
          "packages/shared/src/tenant-transaction.ts",
          "apps/api/src/db/tenant-transaction.test.ts",
        ],
        jsPlugins: [
          { name: "tenant-sql", specifier: "./tools/lint-plugins/src/tenant-sql-plugin.ts" },
        ],
        rules: { "tenant-sql/no-session-setting": "off" },
      },
      // The title of every test in apps/*/src is written in Japanese, so that the verbose test report reads as a
      // list of what the code guarantees. The rule is in tools/lint-plugins/src/test-title-plugin.ts. Tests of the tools
      // and of the lint plugins themselves are outside this rule.
      {
        files: ["apps/*/src/**/*.test.ts", "apps/*/src/**/*.test.tsx"],
        jsPlugins: [
          { name: "test-title", specifier: "./tools/lint-plugins/src/test-title-plugin.ts" },
        ],
        rules: { "test-title/japanese-title": "error" },
      },
      // React rules (hooks, keys, state in effects) and JSX accessibility (alt text, anchors, keyboard
      // handlers). Oxlint's default rules are each plugin's correctness category (docs/web-frontend/static-analysis.md).
      // On top of them: a key that is the index of an array, and the effects React says you might not need
      // (eslint-plugin-react-you-might-not-need-an-effect, in the catalog of pnpm-workspace.yaml). Its
      // no-derived-state reports what react/set-state-in-effect reports, and says what to compute during render
      // instead, so the built-in rule is off. apps/web/src/__fixtures__/react.tsx and
      // packages/ui/src/__fixtures__/react.tsx fail `vp check` if one is
      // turned off.
      {
        files: webFiles,
        plugins: ["react", "jsx-a11y"],
        jsPlugins: [
          {
            name: "react-effect",
            specifier: "eslint-plugin-react-you-might-not-need-an-effect",
          },
        ],
        rules: {
          "react/no-array-index-key": "error",
          "react/set-state-in-effect": "off",
          "react-effect/no-derived-state": "error",
          "react-effect/no-chain-state-updates": "error",
          "react-effect/no-event-handler": "error",
          "react-effect/no-adjust-state-on-prop-change": "error",
          "react-effect/no-reset-all-state-on-prop-change": "error",
          "react-effect/no-pass-live-state-to-parent": "error",
          "react-effect/no-pass-data-to-parent": "error",
          "react-effect/no-external-store-subscription": "error",
          "react-effect/no-initialize-state": "error",
        },
      },
      // The frontend logs nothing to the browser console (docs/logging/frontend.md).
      // Collect client errors with an error tracking service instead.
      {
        files: webFiles,
        rules: { "no-console": "error" },
      },
      // Imports in apps/web/src name a file in another directory with `@/` (the paths of tsconfig.json), not with
      // `../`; `./` stays for a file in the same directory (docs/web-frontend/component-design.md). apps/web/src
      // has no other no-restricted-imports, so this one carries all of them.
      {
        files: ["apps/web/src/**"],
        rules: {
          "no-restricted-imports": [
            "error",
            {
              patterns: [
                {
                  regex: "^\\.\\./",
                  message:
                    "Import a file in another directory with `@/` (apps/web/src), not `../`.",
                },
              ],
            },
          ],
        },
      },
      // Code that opens an XSS hole (docs/web-frontend/static-analysis.md). The rules are in
      // tools/lint-plugins/src/xss-plugin.ts, because Oxlint's built-in ones cannot say what to write instead.
      // Turning one off takes a disable comment with a reason, and a blanket disable is not allowed.
      {
        files: webFiles,
        jsPlugins: [{ name: "web-xss", specifier: "./tools/lint-plugins/src/xss-plugin.ts" }],
        plugins: ["unicorn"],
        rules: {
          "web-xss/no-html-injection": "error",
          "web-xss/no-javascript-url": "error",
          "web-xss/no-dynamic-code": "error",
          "web-xss/require-disable-reason": "error",
          "unicorn/no-abusive-eslint-disable": "error",
          // web-xss/no-dynamic-code reports eval with a message that says what to write instead.
          "no-eval": "off",
        },
      },
    ],
  },
});
